/**
 * 🧱 Herramienta Bloque en Mano
 *
 * - Muestra en la mano el bloque o estructura real de la ranura seleccionada con todas sus texturas, voxeles 3D de alta definición y rotación activa (R / Shift+R).
 * - Renderizado idéntico y nítido tanto con rotación como en posición neutra (rot 0).
 * - La orientación en la mano está 100% alineada con el mundo (rot [0,0,0]) para que coincida exactamente con cómo se planta al lanzarlo.
 * - Al cambiar de ranura (1-9) o rotar (R / Shift+R), se actualiza inmediatamente.
 * - Clic IZQUIERDO: Lanza el bloque hacia adelante respetando su orientación.
 * - Clic DERECHO: Super lanzamiento con impulso.
 */
(async function () {
  'use strict';

  await game.snippet('lanzar-bloque');

  function claveRanura() {
    if (typeof mc === 'undefined') return 'hab:1-voxel';
    const s = (typeof mc.sel === 'number') ? mc.sel : 0;
    const sk = (mc.slotStruct && mc.slotStruct[s]) || null;
    const id = mc.hotbar && mc.hotbar[s];
    const bk = (id && mc.blockKey && mc.blockKey[id]) || null;
    let base = sk || bk || 'hab:1-voxel';

    // Resolver clave canónica del asset 3D completo
    if (typeof mcMatKey === 'function') {
      const kMat = mcMatKey(base, String(base).toLowerCase());
      if (kMat) base = (typeof mcClaveBase === 'function') ? mcClaveBase(kMat) : kMat;
    }
    if (!base.startsWith('asset:') && !base.startsWith('hab:') && typeof mcAssetsRegistry !== 'undefined') {
      const kLow = base.toLowerCase();
      if (mcAssetsRegistry[kLow]) base = 'asset:' + mcAssetsRegistry[kLow];
      else if (mcAssetsRegistry[kLow.replace(/[\s-]+/g, '_')]) base = 'asset:' + mcAssetsRegistry[kLow.replace(/[\s-]+/g, '_')];
      else if (mcAssetsRegistry[kLow.replace(/_/g, '-')]) base = 'asset:' + mcAssetsRegistry[kLow.replace(/_/g, '-')];
    }

    const rot = (typeof mcPreviewOri === 'function') ? mcPreviewOri() : 0;
    if (rot && typeof mcClaveConOri === 'function') return mcClaveConOri(base, rot);
    if (rot) return base + '@' + rot;
    return base;
  }

  function actualizaMano() {
    if (typeof mc === 'undefined' || !mc.herrExtra || !mc.herrExtra.bloque) return;
    const k = claveRanura();
    if (k && k !== mc.herrExtra.bloque.dibujo) {
      mc.herrExtra.bloque.dibujo = k;
      mc._heldToolKey = null; // Fuerza a mcSyncHeldToolStruct a refrescar el asset de la mano
    }
  }

  game.herramientas.define('bloque', {
    dibujo: claveRanura(),
    nombre: '🧱 Bloque en Mano',
    mira: '◈',
    ayuda: 'bloque · clic izq: lanzar bloque · clic dcho: super tiro · 1-9: ranura · R / Shift+R: rotar',
    pos: [0.65, -0.48, 0.15],
    rot: [0, 0, 0], // Alineación directa y fiel 1:1 con la cámara y el mundo
    escala: 0.35,
    gesto: { dur: 0.25, windupP: 0.15, strikeP: 0.40, windupRot: -30, chopRot: 40, lift: 0.10, drop: 0.03, reach: 0.30 },
    gestoBotones: [0, 2],
    anima(e) {
      actualizaMano();
      const q = (e.disparo < 0) ? 1 : 0;
      return {
        pos: [0, Math.sin(e.t * 1.4) * 0.010 * q, 0],
        rot: [0, 0, Math.sin(e.t * 0.9) * 2.0 * q]
      };
    },
    izquierdo() {
      if (typeof game.lanzarBloque === 'function') game.lanzarBloque({ velocidad: 32, gravedad: 11.5 });
    },
    derecho() {
      if (typeof game.lanzarBloque === 'function') game.lanzarBloque({ velocidad: 45, gravedad: 9.0 });
      const cp = Math.cos(mc.pitch || 0);
      mc.vel[0] = -Math.sin(mc.yaw || 0) * cp * 8.5;
      mc.vel[2] = -Math.cos(mc.yaw || 0) * cp * 8.5;
      mc.vel[1] = Math.max(mc.vel[1], 2.8 * Math.sqrt(mc.scale || 1));
      mc.onGround = false;
    }
  });

  actualizaMano();
  game.playerTool = 'bloque';
  toast('🧱 Bloque en mano listo');
})();
